import json,re,subprocess,hashlib
from pathlib import Path
scratch=Path('/tmp/noc-inventory-20261116')
a=json.loads((scratch/'audit.json').read_text())
repo=Path('/home/mingwei/noc_rtl')
results=[]
for cohort in a['cohorts']:
    build=cohort['build']
    wave=repo/cohort['waveform']
    header=scratch/(build+'-header.vcd')
    command=['fsdb2vcd',str(wave),'-o',str(header),'-bt','0ns','-et','1ns']
    if not header.exists():
        with (scratch/(build+'-header.log')).open('w') as log:
            subprocess.check_call(command,cwd=str(scratch),stdout=log,stderr=subprocess.STDOUT)
    scopes=[]
    counts={k:0 for k in ['axi_source','axi_device','physical_link','router_fifo','router_arbiter','router_routing','NI']}
    samples={k:[] for k in counts}
    nodes={k:set() for k in counts}
    declarations=0
    with header.open() as f:
        for line in f:
            parts=line.split()
            if not parts:continue
            if parts[0]=='$scope':
                scopes.append(parts[2])
            elif parts[0]=='$upscope':
                scopes.pop()
            elif parts[0]=='$var':
                declarations+=1
                path='.'.join(scopes)+'.'+parts[4]
                tags=[]
                if '.source_bus.' in path and parts[4] in ['arvalid','arready','rvalid','rready','rlast','araddr','arid','rid']:
                    tags.append('axi_source')
                if '.device_bus.' in path and parts[4] in ['arvalid','arready','rvalid','rready','rlast','araddr','arid','rid']:
                    tags.append('axi_device')
                if path.startswith('tb_top.i_router.') and parts[4] in ['RXREQVLD','RXREQRDY','TXREQVLD','TXREQRDY','RXRSPVLD','RXRSPRDY','TXRSPVLD','TXRSPRDY','RXDATVLD','RXDATRDY','TXDATVLD','TXDATRDY']:
                    tags.append('physical_link')
                if '.i_router.gen_router[' in path:
                    if '.i_fifo.' in path and parts[4] in ['full_o','empty_o','push_i','pop_i','usage_o']:
                        tags.append('router_fifo')
                    if re.search(r'\.(?:i_arb[^.]*|i_packet_rr_arbiter|i_switch_allocator)\.',path) and parts[4] in ['req_i','grant_o','select_o','ready_i','selected_input','req_reg','tail_reg']:
                        tags.append('router_arbiter')
                    if parts[4] in ['route_mask','route_reg','active_reg','computed_route','branch_valid','branch_ready']:
                        tags.append('router_routing')
                if re.search(r'\.(i_ni|u_ni)\.',path) and parts[4] in ['RXREQVLD','RXREQRDY','TXREQVLD','TXREQRDY','RXRSPVLD','RXRSPRDY','TXRSPVLD','TXRSPRDY','RXDATVLD','RXDATRDY','TXDATVLD','TXDATRDY','req_valid','req_ready','rsp_valid','rsp_ready']:
                    tags.append('NI')
                for key in tags:
                    counts[key]+=1
                    match=re.search(r'gen_(?:node|router)\[(\d+)\]',path)
                    if match:nodes[key].add(int(match.group(1)))
                    if len(samples[key])<10:
                        samples[key].append(path)
            elif parts[0]=='$enddefinitions':
                break
    results.append(dict(build=build,source_manifest_sha256=cohort['source_manifest_sha256'],
        representative_fsdb=str(wave.relative_to(repo)),command=command,
        fsdb_sha256=next(r['fsdb_sha256'] for r in a['inventory'] if r['result'] in str(wave) and r['build']==build),
        header_sha256=hashlib.sha256(header.read_bytes()).hexdigest(),
        declarations=declarations,categories=counts,nodes={k:sorted(v) for k,v in nodes.items()},samples=samples,
        scope='Full hierarchy declarations from 0-1ns export; signal availability only, dynamic event pairing not yet verified'))
    print('SIGNALS',build,counts,{k:len(v) for k,v in nodes.items()},flush=True)
(scratch/'signals.json').write_text(json.dumps(results,indent=2)+'\n')
